CREATE TABLE IF NOT EXISTS public."populationCohort" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "locationId" integer NOT NULL REFERENCES public."worldLocation"("id") ON DELETE CASCADE ON UPDATE CASCADE,
  "name" text NOT NULL,
  "race" text NOT NULL DEFAULT 'Sin especificar',
  "occupation" text NOT NULL DEFAULT 'Sin especificar',
  "socialClass" text NOT NULL DEFAULT 'Sin especificar',
  "ageGroup" text NOT NULL DEFAULT 'Mixta',
  "population" bigint NOT NULL DEFAULT 0 CHECK ("population" >= 0),
  "wealth" bigint NOT NULL DEFAULT 0 CHECK ("wealth" >= 0),
  "birthRate" double precision NOT NULL DEFAULT 0.012 CHECK ("birthRate" >= 0 AND "birthRate" <= 1),
  "deathRate" double precision NOT NULL DEFAULT 0.008 CHECK ("deathRate" >= 0 AND "deathRate" <= 1),
  "migrationRate" double precision NOT NULL DEFAULT 0 CHECK ("migrationRate" >= -1 AND "migrationRate" <= 1),
  "productivity" double precision NOT NULL DEFAULT 1 CHECK ("productivity" >= 0),
  "consumption" double precision NOT NULL DEFAULT 1 CHECK ("consumption" >= 0),
  "behavior" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "active" boolean NOT NULL DEFAULT true,
  "createdAt" timestamptz NOT NULL DEFAULT now(),
  "updatedAt" timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS "populationCohort_locationId_active_idx"
  ON public."populationCohort"("locationId", "active");
CREATE INDEX IF NOT EXISTS "populationCohort_race_idx"
  ON public."populationCohort"("race");
CREATE INDEX IF NOT EXISTS "populationCohort_occupation_idx"
  ON public."populationCohort"("occupation");

CREATE TABLE IF NOT EXISTS public."worldSimulationRun" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "simulationType" text NOT NULL,
  "periodKey" text NOT NULL UNIQUE,
  "status" text NOT NULL DEFAULT 'COMPLETED',
  "startedAt" timestamptz NOT NULL DEFAULT now(),
  "completedAt" timestamptz NOT NULL DEFAULT now(),
  "summary" jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE INDEX IF NOT EXISTS "worldSimulationRun_type_completed_idx"
  ON public."worldSimulationRun"("simulationType", "completedAt");

ALTER TABLE public."populationCohort" ENABLE ROW LEVEL SECURITY;

ALTER TABLE public."worldSimulationRun" ENABLE ROW LEVEL SECURITY;
